			"javascript:alert(1)",
			"https://user:pass@app.example.test/",
		])
			assert.throws(
				() =>
					renderMagicLinkEmail({
						appName: "Starter",
						url: unsafe,
						appBaseUrl: "https://app.example.test",
					}),
				EmailError,
			);
	});
